initial
begin
  clk = 0;
  clk_cntr = 1;
  forever
  begin
    clk = ~clk;
    #5;
    if (clk) clk_cntr = clk_cntr + 1;
    if (clk) if ((clk_cntr % 1000) === 0) $display("clk_cntr:%05d %t", clk_cntr, $time);
  end
end
initial
begin
  rstn = 0;
  clr =0;
  repeat (10) @ (posedge clk);
  rstn = 1;
end

initial
begin
  int timeoutfec;
  int ret;
  repeat (1) @ (posedge rstn);
  repeat (10) @ (posedge clk);
  repeat (20000) @(posedge clk); //around 802clks //100clks for chien //2000clks seems to be correct
  //ret = $value$plusargs ("timeoutfec=%0d", timeoutfec);
  timeoutfec = 0;
  repeat (timeoutfec) @(posedge clk);
  $display("RS:finsh called timeout :%0d %t", timeoutfec, $time);
  $finish();
end

